ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
portalfija_data: {
    compensacion_portabilidad:{
        id: payload.PortabilityCompensationIN.PortabilityCompensationInput.portalfija_data.PortabilityCompensation.Id,
        cuenta: payload.PortabilityCompensationIN.PortabilityCompensationInput.portalfija_data.PortabilityCompensation.Account,
        horas: payload.PortabilityCompensationIN.PortabilityCompensationInput.portalfija_data.PortabilityCompensation.Hours
    }
}
}

%dw 2.0
output application/json
---
{
  "PortabilityCompensationOUT": {
    "WSResponseHeader2": {
      "System": {
        "name": vars.nameHeader,
        "correlationID": vars.correlationIdHeader,
        "processingServer": p('template.portabilityCompensationIntf.processingServer')
      },
      "Service": {
        "status": p('template.portabilityCompensationIntf.status'),
        "responseDate": vars.date
      },
    },
    "PortabilityCompensationOutput": {
      "ResponseService": {
      	"Id": payload.portalfija_data.idRegistro,
        "Result": payload.portalfija_data.resultado,
        "DescriptionError": payload.portalfija_data.descError
      }
    }
  }
}

%dw 2.0
output application/json
---
{
  "PortabilityCompensationOUT": {
    "WSResponseHeader2": {
      "System": {
        "name": vars.nameHeader,
        "correlationID": vars.correlationIdHeader,
        "processingServer": p('template.portabilityCompensationIntf.processingServer')
      },
      "Service": {
        "status": p('template.portabilityCompensationIntf.status400'),
        "responseDate": vars.date,
        "statusDetail": {
          "errorCode": payload.portalfija_data.resultado,
          "errorMessage": payload.portalfija_data.descError
        }
      }
    },
    "PortabilityCompensationOutput": {
      "ResponseService": {
        "Result": "E",
        "DescriptionError": payload.portalfija_data.descError
      }
    }
  }
}
